      hit.setAttribute('x',left-5);hit.setAttribute('y',ys[ki]-half);hit.setAttribute('width',Math.max(20,right-left+10));hit.setAttribute('height',half*2);hit.setAttribute('fill','transparent');hit.setAttribute('stroke','none');hit.setAttribute('class','score-hit');hit.setAttribute('tabindex','0');hit.setAttribute('role','button');
