  const renderer=new VF.Renderer(div,VF.Renderer.Backends.SVG); renderer.resize(W,H); const ctx=renderer.getContext();ctx.setFillStyle('#172238');ctx.setStrokeStyle('#172238');
  if(pi===0){ ctx.setFont('IBM Plex Sans KR, Arial',20,'bold'); ctx.fillText(opt.title||'',M,34); ctx.setFont('IBM Plex Sans KR, Arial',12); ctx.fillText('♩ = '+score.bpm+(opt.subtitle?'   ·   '+opt.subtitle:''),M,54); }
  if(pages.length>1){ ctx.setFont('IBM Plex Sans KR, Arial',11); ctx.fillText(`${opt.title||''}  ${pi+1} / ${pages.length}`,W/2-30,H-14); }
