      const fmt=new VF.Formatter(); voices.forEach(v=>fmt.joinVoices([v])); fmt.format(voices,stT.getNoteEndX()-stT.getNoteStartX()-14);
      voices.forEach((v,vi)=>v.draw(ctx,vi===0?stT:stB)); beams.forEach(b=>b.setContext(ctx).draw());
