 const mic={config:MicCore.normalize(),saved:false,open:false,opener:null,phase:'idle',token:0,capture:null,test:null,last:null,error:'',message:'',devices:[],sessionNote:'브라우저 자동 처리',source:null,liveDb:-160,peakDb:-160,frame:0,lastPaint:0,meta:new WeakMap(),finishing:null,settingsLoaded:false};
