 function uiCommitProjects(projects,lastId){return new Promise((resolve,reject)=>{if(typeof DB==='undefined'||!DB.db)return reject(Error('이 브라우저'+'의 저장소를 사용할 수 없습니다. 현재 곡은 그대로 두었습니다. 파일 → 곡 파일 내보내기로 백업하세요.'));let tx,done=false;const finish=e=>{if(done)return;done=true;clearTimeout(timer);e?reject(e):resolve();};const timer=setTimeout(()=>{try{tx?.abort();}catch(_){}finish(Error('저장 확인 시간이 초과되었습니다. 현재 곡은 유지했습니다.'));},10000);try{tx=DB.db.transaction(['projects','meta'],'readwrite');tx.oncomplete=()=>finish();tx.onerror=tx.onabort=()=>finish(tx.error||Error('곡을 저장하지 못했습니다. 현재 곡은 유지했습니다.'));for(const p of projects)tx.objectStore('projects').put(p);if(lastId)tx.objectStore('meta').put(lastId,'last');}catch(e){try{tx?.abort();}catch(_){}finish(e);}});}
